snippet_css:
:root{
  --bg: #F3EEE3;
  --fg: #14284B;
  --muted: #4F5A75;
  --surface: #FFFFFF;
  --border: #C3B9A2;
  --accent: #C8102E;
  --accent-fg: #FFFFFF;
  --radius: 3px;
  --radius-sm: 2px;
  --shadow: 0 2px 0 rgba(20,40,75,.16);
  --btn-shadow: 0 4px 0 rgba(20,40,75,.35);
  --art-bg: linear-gradient(180deg,#4A90B8,#14284B);
  --media-bg: linear-gradient(180deg,#8FB6D2,#4A90B8);
  --cta-bg: #14284B;
  --input-bg: #FFFFFF;
  --ok: #1E7A4B;
  --warn: #C8102E;
  --font-display: 'Playfair Display','Noto Serif TC',serif;
  --font-body: 'Source Sans 3','Noto Sans TC',sans-serif;
  --font-mono: 'Allerta Stencil',ui-monospace,Menlo,monospace;
  --focus-ring: var(--accent);
}

